    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If A x B = B x A for two non- empty sets, what can you conclude about the sets?', '["They are disjoint","A = B","One is a proper subset of the other","They have no elements in common"]'::jsonb, 'B', 1, 'a04cf2db1a37', null),
